CREATE TABLE sys_department(id BIGINT PRIMARY KEY, parent_id BIGINT, name VARCHAR(100) NOT NULL, code VARCHAR(50) NOT NULL UNIQUE, sort_order INT DEFAULT 0, status TINYINT DEFAULT 1);
CREATE TABLE sys_user(id BIGINT PRIMARY KEY, department_id BIGINT, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(50) NOT NULL, email VARCHAR(100), mobile VARCHAR(30), status TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sys_role(id BIGINT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(50) NOT NULL, status TINYINT DEFAULT 1);
CREATE TABLE sys_user_role(user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,PRIMARY KEY(user_id,role_id));
CREATE TABLE sys_menu(id BIGINT PRIMARY KEY,parent_id BIGINT,name VARCHAR(50) NOT NULL,path VARCHAR(200),permission_code VARCHAR(100),menu_type VARCHAR(20),sort_order INT DEFAULT 0,status TINYINT DEFAULT 1);
CREATE TABLE sys_role_menu(role_id BIGINT NOT NULL,menu_id BIGINT NOT NULL,PRIMARY KEY(role_id,menu_id));
CREATE TABLE sys_dictionary(id BIGINT PRIMARY KEY,dict_type VARCHAR(50) NOT NULL,item_code VARCHAR(50) NOT NULL,item_label VARCHAR(100) NOT NULL,item_value VARCHAR(200),sort_order INT DEFAULT 0,status TINYINT DEFAULT 1,UNIQUE(dict_type,item_code));
CREATE TABLE sys_operation_log(id BIGINT PRIMARY KEY,operator_id BIGINT,module VARCHAR(50),operation VARCHAR(100),request_method VARCHAR(10),request_uri VARCHAR(300),request_ip VARCHAR(50),success TINYINT,error_message VARCHAR(500),duration_ms BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE approval_instance(id BIGINT PRIMARY KEY,business_type VARCHAR(30) NOT NULL,business_id BIGINT NOT NULL,applicant_id BIGINT NOT NULL,status VARCHAR(30) NOT NULL,current_node VARCHAR(50),version INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE approval_task(id BIGINT PRIMARY KEY,instance_id BIGINT NOT NULL,assignee_id BIGINT NOT NULL,node_code VARCHAR(50) NOT NULL,status VARCHAR(30) NOT NULL,comment_text VARCHAR(500),handled_at TIMESTAMP);
CREATE TABLE leave_application(id BIGINT PRIMARY KEY,applicant_id BIGINT NOT NULL,leave_type VARCHAR(30) NOT NULL,start_time TIMESTAMP NOT NULL,end_time TIMESTAMP NOT NULL,duration DECIMAL(8,2),reason VARCHAR(500),business_status VARCHAR(30) NOT NULL,approval_instance_id BIGINT,version INT DEFAULT 0);
CREATE TABLE project_application(id BIGINT PRIMARY KEY,applicant_id BIGINT NOT NULL,project_name VARCHAR(200) NOT NULL,project_code VARCHAR(50),owner_department_id BIGINT,budget DECIMAL(16,2),summary VARCHAR(1000),business_status VARCHAR(30) NOT NULL,approval_instance_id BIGINT,version INT DEFAULT 0);
